+    CHECK_NOTERROR(devices::Entry::parse("c 1:5 rwm")),
+    CHECK_NOTERROR(devices::Entry::parse("c 1:7 rwm")),
+    CHECK_NOTERROR(devices::Entry::parse("c 5:0 rwm")),
+    CHECK_NOTERROR(devices::Entry::parse("c 1:9 rwm")),
